CREATE TABLE league_mappings(canonical_id TEXT PRIMARY KEY, name TEXT NOT NULL, format TEXT NOT NULL CHECK(format IN ('league','cup')), api_football_id INTEGER, football_data_code TEXT, last_verified_at_utc TEXT, status TEXT NOT NULL CHECK(status IN ('ok','warning','stale')));
CREATE TABLE events(event_id TEXT PRIMARY KEY, competition_code TEXT NOT NULL, home_team TEXT NOT NULL, away_team TEXT NOT NULL, kickoff_utc TEXT NOT NULL, match_status TEXT NOT NULL CHECK(match_status IN ('scheduled','finished','postponed','cancelled','suspended','rescheduled')), previous_kickoff_utc TEXT, new_kickoff_utc TEXT, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL);
CREATE TABLE snapshots(snapshot_id INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL REFERENCES events(event_id), market TEXT NOT NULL, selection TEXT NOT NULL, odds REAL NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('valid','gap','skipped')), skip_reason TEXT CHECK(skip_reason IN ('daily_cap_reached','too_far_from_kickoff')), captured_at_utc TEXT NOT NULL);
CREATE TABLE reference_odds(reference_id INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL REFERENCES events(event_id), source TEXT NOT NULL, market TEXT NOT NULL, selection TEXT NOT NULL, odds REAL NOT NULL, captured_at_utc TEXT NOT NULL);
CREATE TABLE model_versions(model_version_id INTEGER PRIMARY KEY AUTOINCREMENT, competition_code TEXT NOT NULL, train_until_utc TEXT NOT NULL, matches_count INTEGER NOT NULL, hyperparams_json TEXT NOT NULL, log_likelihood REAL, created_at_utc TEXT NOT NULL);
CREATE TABLE model_probabilities(prob_id INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL REFERENCES events(event_id), model_version_id INTEGER NOT NULL REFERENCES model_versions(model_version_id), market TEXT NOT NULL, selection TEXT NOT NULL, probability REAL NOT NULL CHECK(probability > 0 AND probability < 1), created_at_utc TEXT NOT NULL);
CREATE TABLE manual_odds(manual_id INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL REFERENCES events(event_id), market TEXT NOT NULL, selection TEXT NOT NULL, odds REAL NOT NULL CHECK(odds > 1.0), captured_at_utc TEXT NOT NULL, created_at_utc TEXT NOT NULL);
CREATE TABLE bets(bet_id INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL REFERENCES events(event_id), market TEXT NOT NULL, selection TEXT NOT NULL, manual_odds REAL NOT NULL, stake REAL NOT NULL, ev REAL NOT NULL, model_probability REAL NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','won','lost','void','cancelled')), idempotency_key TEXT NOT NULL UNIQUE, created_at_utc TEXT NOT NULL, closed_at_utc TEXT);
CREATE TABLE decision_explanation(bet_id INTEGER PRIMARY KEY REFERENCES bets(bet_id), model_version_id INTEGER NOT NULL REFERENCES model_versions(model_version_id), decision_rules_version TEXT NOT NULL, sharp_odds_used REAL, sharp_source TEXT, snapshot_id_used INTEGER REFERENCES snapshots(snapshot_id), devig_method TEXT NOT NULL, model_probability REAL NOT NULL, implied_probability REAL NOT NULL, ev REAL NOT NULL, edge_pct REAL NOT NULL, decision TEXT NOT NULL, reasons_json TEXT NOT NULL);
CREATE TABLE decision_logs(decision_log_id INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL, competition_code TEXT NOT NULL, market TEXT NOT NULL, selection TEXT NOT NULL, reason_code TEXT NOT NULL, ev REAL, created_at_utc TEXT NOT NULL);
CREATE TABLE scheduled_closures(bet_id INTEGER PRIMARY KEY REFERENCES bets(bet_id), scheduled_for_utc TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','processing','done','failed')), attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT);
CREATE TABLE closing_odds(bet_id INTEGER PRIMARY KEY REFERENCES bets(bet_id), closing_odds REAL, source TEXT, fallback_reason TEXT, captured_at_utc TEXT);
CREATE TABLE clv_records(bet_id INTEGER PRIMARY KEY REFERENCES bets(bet_id), clv_pct REAL, entry_implied_prob REAL, closing_fair_prob REAL, beat_closing_line INTEGER, calculated_at_utc TEXT NOT NULL);
CREATE TABLE bankroll_history(entry_id INTEGER PRIMARY KEY AUTOINCREMENT, amount_delta REAL NOT NULL, balance_after REAL NOT NULL, reason TEXT NOT NULL, bet_id INTEGER REFERENCES bets(bet_id), created_at_utc TEXT NOT NULL);
CREATE TABLE audit_log(audit_id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT, payload_hash TEXT, outcome TEXT NOT NULL, created_at_utc TEXT NOT NULL);
CREATE TABLE performance_snapshots(snapshot_id INTEGER PRIMARY KEY AUTOINCREMENT, source_type TEXT NOT NULL CHECK(source_type IN ('historical_archive','radar_snapshot')), computed_at_utc TEXT NOT NULL, report_json TEXT NOT NULL);
CREATE INDEX index_events_kickoff_utc ON events(kickoff_utc);
CREATE INDEX index_events_match_status ON events(match_status);
CREATE INDEX index_snapshots_event_id_captured_at_utc ON snapshots(event_id, captured_at_utc);
CREATE INDEX index_snapshots_status ON snapshots(status);
CREATE INDEX index_bets_status ON bets(status);
CREATE INDEX index_decision_logs_competition_code_reason_code_created_at_utc ON decision_logs(competition_code, reason_code, created_at_utc);
CREATE INDEX index_scheduled_closures_status_scheduled_for_utc ON scheduled_closures(status, scheduled_for_utc);
